export function throttle<A extends unknown[]>(fn: (...args: A) => void, ms: number, now: () => number): (...args: A) => void {
  let last = -Infinity;
  return (...args: A) => {
    const t = now();
    if (t - last >= ms) {
      last = t;
      fn(...args);
    }
  };
}

