import assert from "node:assert/strict";
import { test } from "node:test";
import { throttle } from "../src/timing.ts";

test("throttle", () => {
  let t = 0;
  const calls: number[] = [];
  const f = throttle((n: number) => calls.push(n), 100, () => t);
  f(1);
  t = 50;
  f(2);
  t = 100;
  f(3);
  assert.deepEqual(calls, [1, 3]);
});

